head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gAcptNo;
scwin.gIsurCd;
scwin.gPageSize = 10; //페이지 size
scwin.gTotalCnt = 0; //전체 row
scwin.gPageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호

scwin.vScrenID = 'ULDSTF35810.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusYear(vCurDate, 1)); //  1년전  날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜


    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !불성실지정예고--;
클릭-- > function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) == false) {
        return;
    }
    fn_Search();
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !불성실지정--;
목록검색(유가증권);
사용자;
클릭-- > function() {
    scwin.vCurrPageNo = 0;
    txb_TotalCnt.setValue("총건수 : ");
    var bndListStat = scwin.getChkValue(chb_ListStatCd);
    if (bndListStat == "0") {
        bndListStat = "2"; //채권공시 해제법인

    }
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        //채권매매거래정지
        var url_list = "/UnfaithfulDesign.do?method=trdHaltBond&inputMessageId=TRHALTBOND_IN" + "&outputMessageId=TRHALTBOND_OUT";
        var url_cond = "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&BND_LIST_STAT=" + bndListStat + "&FORM_CD=91680" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

        // 그리드의 데이타 조회
        dts_trdhaltbond_list.DataID = encodeURI(url_list + url_cond);
        dts_trdhaltbond_list.reset();
        $c.cm.ShowWin(grd_trdhistbond_list);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        //채권매매거래정지해제
        var url_list = "/UnfaithfulDesign.do?method=trdHaltBond&inputMessageId=TRHALTBOND_IN" + "&outputMessageId=TRHALTBOND_OUT";
        var url_cond = "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&BND_LIST_STAT=" + bndListStat + "&FORM_CD=91681" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

        // 그리드의 데이타 조회
        dts_trdhaltbond_list_2.DataID = encodeURI(url_list + url_cond);
        dts_trdhaltbond_list_2.reset();
        $c.cm.ShowWin(grd_trdhistbond_list_2);
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        //채권매매거래정지 및 해제
        var url_list = "/UnfaithfulDesign.do?method=trdHaltBond&inputMessageId=TRHALTBOND_IN" + "&outputMessageId=TRHALTBOND_OUT";
        var url_cond = "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&BND_LIST_STAT=" + bndListStat + "&FORM_CD=91682" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

        // 그리드의 데이타 조회
        dts_trdhaltbond_list_3.DataID = encodeURI(url_list + url_cond);
        dts_trdhaltbond_list_3.reset();
        $c.cm.ShowWin(grd_trdhistbond_list_3);
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        //채권매매거래정지 및 상장폐지
        var url_list = "/UnfaithfulDesign.do?method=trdHaltBond&inputMessageId=TRHALTBOND_IN" + "&outputMessageId=TRHALTBOND_OUT";
        var url_cond = "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&BND_LIST_STAT=" + bndListStat + "&FORM_CD=91683" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

        // 그리드의 데이타 조회
        dts_trdhaltbond_delist.DataID = encodeURI(url_list + url_cond);
        dts_trdhaltbond_delist.reset();
        $c.cm.ShowWin(grd_trdhistbond_delist);
    }
};




// 그리드에서 클릭 row의 변수셋팅
//매매거래정지
scwin.fn_setContnId_list = function(obj) {
    scwin.gAcptNo = dts_trdhaltbond_list.getCellData(eval(obj), "ACPT_NO");
    scwin.gIsurCd = dts_trdhaltbond_list.getCellData(eval(obj), "ISUR_CD");
};


