scwin.grd_trdhistbond_list_OnDblClick = function(row, colid) {
    scwin.fn_setContnId_list(row);
    if (colid == "COM_NM") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "BND_ISU_NM") {
        //2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
    } else if (colid == "DISCLS_PUBL_DDTM") {
        //2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
    } else if (colid == "TRD_HALT_PD_CONTN") {
        //2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
    }
};
