scwin.dts_trdhaltbond_list_OnLoadError = function() {
    $c.stf.alert_error(dts_trdhaltbond_list);
    $c.cm.CloseWin('', grd_trdhistbond_list);
};
scwin.dts_trdhaltbond_list_OnLoadCompleted = function(rowcount) {
    if (dts_trdhaltbond_list.errorMsg) {
        $c.win.alert(dts_trdhaltbond_list.errorMsg);
    } else {
        txb_TotalCnt.setValue("총건수 : " + rowcount);
        //alert(txb_TotalCnt.value );

    }
    $c.cm.CloseWin(rowcount, grd_trdhistbond_list);
};
